-- generated by ghflow.silver (python -m ghflow.commands.silver generate); do not edit
-- Per hour, the silver views together hold exactly the bronze rows (M1-S3): every hour
-- where they differ is a failing row. Bronze is counted from the Parquet files themselves.
with bronze as (
    select cast(date as date) as event_date, cast(hour as integer) as event_hour, count(*) as n
    from read_parquet('{{ var("bronze_events") }}', hive_partitioning = true)
    group by all
),
silver as (
    select event_date, event_hour, count(*) as n from {{ ref('silver_commit_comment_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_create_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_delete_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_discussion_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_fork_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_gollum_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_issue_comment_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_issues_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_member_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_public_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_pull_request_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_pull_request_review_comment_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_pull_request_review_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_push_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_release_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_watch_events') }} group by all
    union all
    select event_date, event_hour, count(*) as n from {{ ref('silver_unknown_events') }} group by all
),
silver_by_hour as (
    select event_date, event_hour, sum(n) as n from silver group by all
)
select
    coalesce(b.event_date, s.event_date) as event_date,
    coalesce(b.event_hour, s.event_hour) as event_hour,
    b.n as bronze_rows,
    s.n as silver_rows
from bronze b
full outer join silver_by_hour s using (event_date, event_hour)
where b.n is distinct from s.n
